{
  "facts": [
    {
      "topic": "scope",
      "statement": "The entry compresses fuzzer input with ZSTD_compressStream2, decompresses the result, and checks the regenerated size and bytes.",
      "evidence": [
        {"unit_id": "u-9dc9e88ae722c8cbe085", "start_line": 59, "end_line": 67, "role": "dependency", "dependency_reason": "The compression helper configures the context before streaming."},
        {"unit_id": "u-9dc9e88ae722c8cbe085", "start_line": 69, "end_line": 135, "role": "dependency", "dependency_reason": "These are the entry's streaming compression calls."},
        {"unit_id": "u-9dc9e88ae722c8cbe085", "start_line": 185, "end_line": 205, "role": "dependency", "dependency_reason": "The entry invokes compression and decompression and makes the existing round-trip assertions."}
      ]
    , "absence_claim": false, "audited_unit_ids": []},
    {
      "topic": "contract",
      "statement": "In the supplied before source, windowLog and hashLog are accepted as explicit compression parameters up to ZSTD_WINDOWLOG_MAX and ZSTD_HASHLOG_MAX, respectively; nonzero values are bounds checked and stored.",
      "evidence": [
        {"unit_id": "u-860860e3395d8f95d959", "start_line": 425, "end_line": 444, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-860860e3395d8f95d959", "start_line": 789, "end_line": 799, "role": "primary", "dependency_reason": ""}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "target_route",
      "statement": "The target's parameter generator draws windowLog and hashLog with an upper argument of 15, then passes the parameters through ZSTD_adjustCParams. FUZZ_setRandomParameters writes the resulting values to the compression context.",
      "evidence": [
        {"unit_id": "u-194debf8ea4cd55b47ba", "start_line": 44, "end_line": 56, "role": "dependency", "dependency_reason": "This is the target's log selection and adjustment route."},
        {"unit_id": "u-d12ebcf33fdbb6d713f7", "start_line": 101, "end_line": 110, "role": "dependency", "dependency_reason": "The generated values become requested context parameters."},
        {"unit_id": "u-9dc9e88ae722c8cbe085", "start_line": 63, "end_line": 67, "role": "dependency", "dependency_reason": "The streaming helper invokes that parameter route."}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "contract",
      "statement": "In the before source, ZSTD_adjustCParams clamps parameters to API bounds and treats source size zero as unknown. Its internal adjustment can reduce windowLog for small known input and reduce hashLog relative to the adjusted window; the supplied code does not establish the numerical maximum of either log.",
      "evidence": [
        {"unit_id": "u-860860e3395d8f95d959", "start_line": 1388, "end_line": 1408, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-860860e3395d8f95d959", "start_line": 1452, "end_line": 1515, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-860860e3395d8f95d959", "start_line": 1556, "end_line": 1564, "role": "primary", "dependency_reason": ""}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "target_route",
      "statement": "Before streaming initialization, the compressor obtains level based parameters, applies explicitly requested compression parameters as overrides, and adjusts them for the stream. Thus the level defaults are a possible route to inspect, but the target's explicit log settings take precedence when present.",
      "evidence": [
        {"unit_id": "u-860860e3395d8f95d959", "start_line": 1569, "end_line": 1595, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-860860e3395d8f95d959", "start_line": 6103, "end_line": 6135, "role": "dependency", "dependency_reason": "Streaming initialization applies the adjusted requested parameters."},
        {"unit_id": "u-d12ebcf33fdbb6d713f7", "start_line": 101, "end_line": 110, "role": "dependency", "dependency_reason": "The target explicitly requests both logs."}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "alternative",
      "statement": "The target also varies ZSTD_c_ldmHashLog up to 16. That setting is named separately from ZSTD_c_hashLog and does not itself show that the frozen main hashLog or windowLog configuration is reached.",
      "evidence": [
        {"unit_id": "u-d12ebcf33fdbb6d713f7", "start_line": 103, "end_line": 117, "role": "dependency", "dependency_reason": "These calls distinguish the main compression logs from the LDM hash log."},
        {"unit_id": "u-860860e3395d8f95d959", "start_line": 436, "end_line": 444, "role": "primary", "dependency_reason": ""}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "configuration",
      "statement": "The supplied build recipe enters tests/fuzz and delegates building all fuzzers to ./fuzz.py build all. It does not itself state the target's effective compile configuration.",
      "evidence": [
        {"unit_id": "u-043cf5aa9ced10a35cb6", "start_line": 19, "end_line": 26, "role": "dependency", "dependency_reason": "The recipe delegates the target build to fuzz.py."}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "consequence",
      "statement": "The frozen high-log coverage question remains conditional in this continuation: the target's explicit selection has an upper argument of 15, while the supplied source expresses supported upper bounds only as macros. These lines alone do not establish a build-supported distinct setting above 15.",
      "evidence": [
        {"unit_id": "u-860860e3395d8f95d959", "start_line": 436, "end_line": 444, "role": "primary", "dependency_reason": ""},
        {"unit_id": "u-194debf8ea4cd55b47ba", "start_line": 44, "end_line": 56, "role": "dependency", "dependency_reason": "The target's generator supplies the proposed cap."},
        {"unit_id": "u-043cf5aa9ced10a35cb6", "start_line": 19, "end_line": 24, "role": "dependency", "dependency_reason": "The recipe delegates decisive build settings."}
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    }
  ],
  "missing_information": [
    "Definitions and effective build values of ZSTD_WINDOWLOG_MAX and ZSTD_HASHLOG_MAX.",
    "The delegated fuzz target and library build configuration that determines those effective values."
  ],
  "requested_symbols": ["ZSTD_WINDOWLOG_MAX", "ZSTD_HASHLOG_MAX"],
  "requested_paths": ["tests/fuzz/fuzz.py", "tests/fuzz/Makefile", "lib/libzstd.mk"]
}
